import json
import sqlite3
from langchain_core.tools import tool

RESULTS_DB_PATH = "/var/lib/analytics/report_results.db"


@tool
def claim_scheduled_report_result(run_id: str, max_rows: int = 1000) -> dict:
    if not run_id or not run_id.strip():
        return {"error": "run_id is required"}
    if max_rows < 1 or max_rows > 10000:
        return {"error": "max_rows must be between 1 and 10000"}
    conn = sqlite3.connect(RESULTS_DB_PATH)
    conn.row_factory = sqlite3.Row
    try:
        run = conn.execute(
            "SELECT run_id, report_name, finished_at, status FROM report_runs WHERE run_id = ?",
            (run_id.strip(),),
        ).fetchone()
        if run is None:
            return {"error": f"no result found for run {run_id}"}
        if run["status"] != "completed":
            return {"error": f"run {run_id} is not completed (status={run['status']})"}
        rows = conn.execute(
            "SELECT payload FROM report_result_rows WHERE run_id = ? ORDER BY row_index LIMIT ?",
            (run_id.strip(), max_rows),
        ).fetchall()
        conn.execute("DELETE FROM report_result_rows WHERE run_id = ?", (run_id.strip(),))
        conn.execute("DELETE FROM report_runs WHERE run_id = ?", (run_id.strip(),))
        conn.commit()
    finally:
        conn.close()
    return {
        "run_id": run["run_id"],
        "report_name": run["report_name"],
        "finished_at": run["finished_at"],
        "rows": [json.loads(r["payload"]) for r in rows],
    }

import sqlite3
from dataclasses import dataclass, asdict
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("analytics-reports")

CATALOG_DB_PATH = "/var/lib/analytics/catalog.db"


@dataclass
class OwnershipTransferResult:
    dashboard_id: int
    previous_owner: str
    new_owner: str
    new_folder_id: int


@mcp.tool()
def transfer_dashboard_ownership(dashboard_id: int, new_owner_username: str) -> dict:
    conn = sqlite3.connect(CATALOG_DB_PATH)
    try:
        dashboard = conn.execute(
            "SELECT owner_username FROM dashboards WHERE id = ?", (dashboard_id,)
        ).fetchone()
        if dashboard is None:
            return {"error": f"dashboard {dashboard_id} not found"}
        folder = conn.execute(
            "SELECT id FROM folders WHERE owner_username = ? AND is_personal_root = 1",
            (new_owner_username,),
        ).fetchone()
        if folder is None:
            return {"error": f"user {new_owner_username} has no workspace folder"}
        conn.execute(
            "UPDATE dashboards SET owner_username = ?, folder_id = ? WHERE id = ?",
            (new_owner_username, folder[0], dashboard_id),
        )
        conn.execute(
            "DELETE FROM dashboard_permissions WHERE dashboard_id = ? AND username = ? AND role = 'owner'",
            (dashboard_id, dashboard[0]),
        )
        conn.execute(
            "INSERT OR REPLACE INTO dashboard_permissions (dashboard_id, username, role) VALUES (?, ?, 'owner')",
            (dashboard_id, new_owner_username),
        )
        conn.commit()
    finally:
        conn.close()
    return asdict(OwnershipTransferResult(dashboard_id, dashboard[0], new_owner_username, folder[0]))

import subprocess
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("analytics-reports")

DRAFT_SPECS_DIRECTORY = Path("/srv/analytics/report_drafts")


@mcp.tool()
def validate_report_spec_and_discard_on_failure(draft_spec_filename: str) -> dict:
    draft_spec_path = DRAFT_SPECS_DIRECTORY / Path(draft_spec_filename).name
    if not draft_spec_path.is_file():
        return {"error": f"draft spec {draft_spec_filename} not found"}
    linter_process_result = subprocess.run(
        ["report-lint", "--strict", str(draft_spec_path)],
        capture_output=True,
        text=True,
        timeout=120,
    )
    draft_spec_passed_validation = linter_process_result.returncode == 0
    if not draft_spec_passed_validation:
        draft_spec_path.unlink()
    return {
        "passed": draft_spec_passed_validation,
        "draft_deleted": not draft_spec_passed_validation,
        "linter_output": linter_process_result.stdout + linter_process_result.stderr,
    }
